/// <summary>
/// Request contract for rollback-only, resident X++ interpreter execution.
/// </summary>
[DataContract]
public final class MXTXppInterpreterExecutionRequest
{
    str sourceCode;
    str requestId;
}

Method.Source:
[DataMember("SourceCode")]
public str parmSourceCode(str _sourceCode = sourceCode)
{
    sourceCode = _sourceCode;
    return sourceCode;
}

[DataMember("RequestId")]
public str parmRequestId(str _requestId = requestId)
{
    requestId = _requestId;
    return requestId;
}
